import{_ as a,c as i,o as t,aj as o}from"./chunks/framework.e3UxQEvm.js";const u=JSON.parse('{"title":"Setup","description":"","frontmatter":{"title":"Setup"},"headers":[],"relativePath":"architecture/setup.md","filePath":"architecture/setup.md"}'),r={name:"architecture/setup.md"};function n(s,e,c,l,d,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to “Setup”">​</a></h1><h2 id="pod-setup" tabindex="-1">Pod Setup <a class="header-anchor" href="#pod-setup" aria-label="Permalink to “Pod Setup”">​</a></h2><p>At the first sign-in to the app, the user&#39;s pod is checked, and</p><h3 id="generic" tabindex="-1">Generic <a class="header-anchor" href="#generic" aria-label="Permalink to “Generic”">​</a></h3><p>These are (draft) standard C2C resources.</p><p><a href="https://solid.github.io/webid-profile/" target="_blank" rel="noreferrer">https://solid.github.io/webid-profile/</a></p><h4 id="preferences-file" tabindex="-1">Preferences File <a class="header-anchor" href="#preferences-file" aria-label="Permalink to “Preferences File”">​</a></h4><h4 id="type-indexes" tabindex="-1">Type Indexes <a class="header-anchor" href="#type-indexes" aria-label="Permalink to “Type Indexes”">​</a></h4><p><a href="https://solid.github.io/type-indexes/" target="_blank" rel="noreferrer">https://solid.github.io/type-indexes/</a></p><p>SolidCouch uses both Public and Private Type Index:</p><ul><li>Public - link to hospex document</li><li>Private - link to chat</li></ul><h4 id="inbox" tabindex="-1">Inbox <a class="header-anchor" href="#inbox" aria-label="Permalink to “Inbox”">​</a></h4><p>Publicly appendable directory for notifications. Any authenticated agent can append to it. This is unsafe. We may replace it with an ActivityPub inbox in the future.</p><h3 id="solidcouch-specific" tabindex="-1">SolidCouch-specific <a class="header-anchor" href="#solidcouch-specific" aria-label="Permalink to “SolidCouch-specific”">​</a></h3><h4 id="hospex-document-and-storage" tabindex="-1">Hospex document and storage <a class="header-anchor" href="#hospex-document-and-storage" aria-label="Permalink to “Hospex document and storage”">​</a></h4><p>Hospex document is linked from public type index with predicate <code>hospex:PersonalHospexDocument</code>.</p><p>Typically located at <code>/hospex/[community-identifier]/card</code>.</p><p>Read more in <a href="./hospex-data">Hospex Data</a>.</p><p>It is possible to set up a hospex document for each community, or reuse a hospex document for multiple communities.</p><h2 id="joining-community" tabindex="-1">Joining community <a class="header-anchor" href="#joining-community" aria-label="Permalink to “Joining community”">​</a></h2><p>This involves becoming a member, and sharing data with other members. <a href="./membership">Read more</a></p><h2 id="email-notifications" tabindex="-1">Email notifications <a class="header-anchor" href="#email-notifications" aria-label="Permalink to “Email notifications”">​</a></h2><p>Email notifications need to be set up in order to send information about:</p><ul><li>new messages</li><li>contact requests</li><li>(future) experiences</li></ul><p><a href="./notifications">Read more</a></p>',25)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
